48: export const prettyJSON = (options?: PrettyOptions): MiddlewareHandler => {
49:   const targetQuery = options?.query ?? 'pretty'
50:   return async function prettyJSON(c, next) {
51:     const pretty = options?.force || c.req.query(targetQuery) || c.req.query(targetQuery) === ''
52:     await next()
53:     const contentType = c.res.headers.get('Content-Type')
54:     if (pretty && contentType && jsonContentTypeRegex.test(contentType)) {
55:       // Read from a clone so that the response is kept intact when the body is not parseable as JSON
56:       let obj: unknown
57:       try {
58:         obj = await c.res.clone().json()
59:       } catch {
60:         // e.g. an empty 204 response or a body that is not valid JSON
61:         return
62:       }
63:       await c.res.body?.cancel()
64:       c.res = new Response(JSON.stringify(obj, null, options?.space ?? 2), c.res)
65:       // The length of the body has changed, so remove the stale Content-Length
66:       c.res.headers.delete('Content-Length')
67:     }
