cd <workspace> && ./node_modules/.bin/esbuild src/context.ts --bundle --format=esm --platform=node --outfile=<tmp> --log-level=error && node -e "
import('<tmp>').then(({Context})=>{
  // 1. prepared headers set before c.res assignment
  const c1=new Context(new Request('http://localhost/'));
  c1.header('X-Prepared','yes');
  c1.res = new Response('hi');            // #res was undefined, #preparedHeaders exists
  console.log('1 prepared header after assign:', c1.res.headers.get('x-prepared'));

  // 2. conflicting non-content-type header: old vs new
  const c2=new Context(new Request('http://localhost/'));
  c2.res.headers.set('X-Conflict','OLD');
  c2.res = new Response('hi',{headers:{'X-Conflict':'NEW','X-Only-New':'new'}});
  console.log('2 conflict:', c2.res.headers.get('x-conflict'), 'only-new:', c2.res.headers.get('x-only-new'));

  // 3. cookies old vs new + order
  const c3=new Context(new Request('http://localhost/'));
  c3.res.headers.append('set-cookie','old-a=1; Path=/');
  c3.res.headers.append('set-cookie','old-b=2; Path=/');
  const n=new Response('x'); n.headers.append('set-cookie','new-a=1; Path=/');
  c3.res=n;
  console.log('3 cookies:', c3.res.headers.getSetCookie());

  // 4. old has no cookies, new does
  const c4=new Context(new Request('http://localhost/'));
  c4.res.headers.set('X','1');
  const n4=new Response('x'); n4.headers.append('set-cookie','new-only=1; Path=/');
  c4.res=n4;
  console.log('4 new-only cookie kept:', c4.res.headers.getSetCookie());

  // 5. consumed body assigned into existing res
  const c5=new Context(new Request('http://localhost/'));
  c5.res.headers.set('X','1');
  const used=new Response('body'); await used.text();
  try { c5.res=used; console.log('5 assigned consumed body ok:', c5.res.status); } catch(e){ console.log('5 threw:', e.constructor.name, e.message); }
}).catch(e=>console.error('ERR',e));
"

